import{_ as o,o as e,c as d,a6 as a}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"状态码：3xx 重定向","description":"301/302/303/307/308 的方法改写差异、Location 解析规则与 300/304 的特殊语义。","frontmatter":{"title":"状态码：3xx 重定向","description":"301/302/303/307/308 的方法改写差异、Location 解析规则与 300/304 的特殊语义。","source":"https://daiw.org/manual/http11/status-3xx"},"headers":[],"relativePath":"manual/computer-programming/http11/status-3xx.md","filePath":"manual/computer-programming/http11/status-3xx.md"}'),r={name:"manual/computer-programming/http11/status-3xx.md"};function n(c,t,i,s,l,g){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="状态码-3xx-重定向" tabindex="-1">状态码：3xx 重定向 <a class="header-anchor" href="#状态码-3xx-重定向" aria-label="Permalink to &quot;状态码：3xx 重定向&quot;">​</a></h1><h2 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Location = URI-reference</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>3xx 的核心字段。要点：</p><ul><li>值可以是<strong>相对引用</strong>，接收方 <strong>MUST</strong> 以请求的目标 URI 为基准解析。</li><li>值中的 fragment：若 <code>Location</code> 自身无 fragment，客户端 <strong>SHOULD</strong> 沿用原请求 URI 的 fragment。</li><li><code>Location</code> 在 <code>201</code> 中语义不同——指新建资源，不是重定向。</li><li>值<strong>不做</strong>百分号解码；含非 ASCII 时必须先编码为 URI。</li></ul><h2 id="五个重定向码的差异" tabindex="-1">五个重定向码的差异 <a class="header-anchor" href="#五个重定向码的差异" aria-label="Permalink to &quot;五个重定向码的差异&quot;">​</a></h2><p>唯一需要记的维度是：<strong>后续请求是否保留原方法与请求体</strong>。</p><table tabindex="0"><thead><tr><th>码</th><th>语义</th><th>后续方法</th><th>缓存</th><th>引入</th></tr></thead><tbody><tr><td><code>301 Moved Permanently</code></td><td>永久迁移</td><td><strong>可改写为 GET</strong>（历史行为）</td><td>默认可缓存</td><td>早期</td></tr><tr><td><code>302 Found</code></td><td>临时</td><td><strong>可改写为 GET</strong>（历史行为）</td><td>需显式</td><td>早期</td></tr><tr><td><code>303 See Other</code></td><td>去别处取结果</td><td><strong>MUST 改为 GET</strong></td><td>需显式</td><td>HTTP/1.1</td></tr><tr><td><code>307 Temporary Redirect</code></td><td>临时</td><td><strong>MUST 保留原方法与体</strong></td><td>需显式</td><td>HTTP/1.1</td></tr><tr><td><code>308 Permanent Redirect</code></td><td>永久迁移</td><td><strong>MUST 保留原方法与体</strong></td><td>默认可缓存</td><td>RFC 7538</td></tr></tbody></table><h3 id="_301-302-的方法改写问题" tabindex="-1">301/302 的方法改写问题 <a class="header-anchor" href="#_301-302-的方法改写问题" aria-label="Permalink to &quot;301/302 的方法改写问题&quot;">​</a></h3><p>规范原意是保留方法，但<strong>历史实现</strong>普遍把 <code>POST</code> 后的 <code>301</code>/<code>302</code> 改写成 <code>GET</code>。RFC 9110 承认这一现实：允许（而非要求）改写。</p><p>后果：<code>301</code>/<code>302</code> 对非 GET 请求的行为<strong>不可预测</strong>。工程结论——</p><ul><li>需要<strong>确保改为 GET</strong> → 用 <code>303</code>。</li><li>需要<strong>确保保留方法</strong> → 用 <code>307</code>（临时）或 <code>308</code>（永久）。</li><li><code>301</code>/<code>302</code> 只用于 GET/HEAD 场景。</li></ul><h3 id="_301-308-的缓存影响" tabindex="-1">301/308 的缓存影响 <a class="header-anchor" href="#_301-308-的缓存影响" aria-label="Permalink to &quot;301/308 的缓存影响&quot;">​</a></h3><p>两者默认可缓存且常被浏览器<strong>长期持久化</strong>（甚至无 <code>Cache-Control</code> 时也硬缓存到磁盘）。误发一次 <code>301</code> 到错误目标，用户侧可能长期无法恢复。</p><p>生产建议：新上线的永久重定向先用 <code>302</code>/<code>307</code> 观察，确认无误再改 <code>301</code>/<code>308</code>；或对 <code>301</code> 显式加 <code>Cache-Control: max-age=&lt;较小值&gt;</code>。</p><h2 id="_300-multiple-choices" tabindex="-1">300 Multiple Choices <a class="header-anchor" href="#_300-multiple-choices" aria-label="Permalink to &quot;300 Multiple Choices&quot;">​</a></h2><p>目标资源有多个表示，供客户端选择（<strong>主动式内容协商</strong>）。</p><ul><li><strong>SHOULD</strong> 在体中列出可选表示的清单，格式未规范化。</li><li>可用 <code>Location</code> 指出服务端的首选项。</li><li>默认可缓存。实际部署极少。</li></ul><h2 id="_304-not-modified" tabindex="-1">304 Not Modified <a class="header-anchor" href="#_304-not-modified" aria-label="Permalink to &quot;304 Not Modified&quot;">​</a></h2><p>条件请求命中——客户端的缓存副本仍然有效。<strong>不是重定向</strong>，归在 3xx 是历史分类。</p><p>硬性约束：</p><ul><li><strong>MUST NOT</strong> 有消息体。响应终止于头后的空行。</li><li><strong>MUST</strong> 带若与 <code>200</code> 一起发送时会发的验证器：<code>ETag</code>、<code>Last-Modified</code>（若有）。</li><li><strong>SHOULD</strong> 带在同样情况下会发的 <code>Cache-Control</code>、<code>Content-Location</code>、<code>Date</code>、<code>Expires</code>、<code>Vary</code>。</li><li>可带 <code>Content-Length</code>（指若为 200 时的长度），接收方<strong>不得</strong>据此读体。</li><li>缓存收到 <code>304</code> 后 <strong>MUST</strong> 用响应中的头<strong>更新</strong>已存储的响应，然后把更新后的副本交给客户端。</li></ul><p>详见<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>。</p><h2 id="_305-与-306" tabindex="-1">305 与 306 <a class="header-anchor" href="#_305-与-306" aria-label="Permalink to &quot;305 与 306&quot;">​</a></h2><ul><li><code>305 Use Proxy</code>：<strong>已废弃</strong>（RFC 7231 起）。曾要求客户端经指定代理重发，因存在被劫持风险被移除。客户端 <strong>MUST NOT</strong> 遵循它。</li><li><code>306</code>：<strong>已保留不用</strong>。曾是 <code>Switch Proxy</code> 草案，从未标准化。</li></ul><h2 id="重定向循环" tabindex="-1">重定向循环 <a class="header-anchor" href="#重定向循环" aria-label="Permalink to &quot;重定向循环&quot;">​</a></h2><p>规范<strong>不规定</strong>最大跳数。客户端 <strong>MUST</strong> 自行检测并中断循环（常见上限 20 跳，浏览器多为 20，curl 默认 <code>--max-redirs 50</code>）。</p><p>跨重定向时的安全要求：</p><ul><li>跳到<strong>不同 origin</strong> 时，客户端 <strong>MUST NOT</strong> 携带原 <code>Authorization</code> 字段。</li><li><code>Cookie</code> 按各自域的规则重新计算，不是照抄。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/status-4xx">状态码：4xx 客户端错误</a>。</p>',30)])])}const u=o(r,[["render",n]]);export{p as __pageData,u as default};
